class Solution {
  public:
    int LongestBitonicSequence(vector<int> arr) {
        /**
        *Tabulation Space Optimized Solution
        */
        vector<vector<vector<int>>>dp(arr.size()+1, vector<vector<int>>(arr.size()+1, vector<int>(2,0)));
        vector<vector<int>>curr(arr.size()+1, vector<int>(2,0));
        vector<vector<int>>prev(arr.size()+1, vector<int>(2,0));
        int n = arr.size();
        for(int i=n-1;i>=0;i--){
          for(int j=i-1;j>=-1;j--){
            for(int k=1;k>=0;k--){
              int last;
              if(j == -1) last = INT_MIN;
              else last = arr[j];
              int notTaken = prev[j+1][k];
              int taken = 0;
              if(k == 1){
                  if(arr[i] > last){
                      taken = 1 + prev[i+1][k];
                  }else if(arr[i] < last){
                      taken = 1 + prev[i+1][!k];
                  }
              }else{
                  if(arr[i]<last){
                      taken = 1 + prev[i+1][k];
                  }
              }
              curr[j+1][k] = max(taken, notTaken);
            }
          }
          prev = curr;
        }
        return curr[0][1];
    }
};

