class Solution {
  private:
    int util(int ind, int lastInd, int dir, vector<int> &arr, vector<vector<vector<int>>>&dp){
        if(ind == arr.size()) return 0;
        if(dp[ind][lastInd+1][dir]!=-1)return dp[ind][lastInd+1][dir];
        int last;
        if(lastInd == -1) last = INT_MIN;
        else last = arr[lastInd];
        int notTaken = util(ind+1, lastInd, dir, arr,dp);
        int taken = 0;
        if(dir == 0){
            if(arr[ind] > last){
                taken = 1+util(ind+1, ind, dir, arr,dp);
            }else if(arr[ind] < last){
                taken = 1+util(ind+1, ind, !dir, arr,dp);
            }
        }else{
            if(arr[ind]<last){
                taken = 1+util(ind+1, ind, dir,arr,dp);
            }
        }
        return dp[ind][lastInd+1][dir] = max(taken, notTaken);
    }
  public:
    int LongestBitonicSequence(vector<int> arr) {
        vector<vector<vector<int>>>dp(arr.size(), vector<vector<int>>(arr.size()+1, vector<int>(2,-1)));
        return util(0, -1, 0, arr,dp);
    }
};

```

